  {topic:'Consumer privacy',authority:'California Consumer Privacy Act, Cal. Civ. Code § 1798.100 et seq. (as amended)',why:'Assess whether the business and data fall within the statute and exemptions. Map notice, access/deletion/correction, sharing, sensitive personal information, service-provider contracts, and data-retention duties.',url:'https://oag.ca.gov/privacy/ccpa'},
  {topic:'Telehealth',authority:'Cal. Bus. & Prof. Code § 2290.5',why:'If the product enables delivery of health care by telehealth, check consent, standard of care, documentation, provider licensure, and any profession-specific rules.',url:'https://leginfo.legislature.ca.gov/faces/codes_displaySection.xhtml?lawCode=BPC&sectionNum=2290.5.'}
