const isOtherValue=v=>['other','other-drug','other-legal'].includes(v);const otherKey=id=>`${id}Other`;const otherEntries=(pathway,answers)=>pathways[pathway].questions.filter(q=>isOtherValue(answers[q.id])&&answers[otherKey(q.id)]?.trim()).map(q=>({question:q.title,text:answers[otherKey(q.id)].trim()}));function scoreOption(option,answers){const priority=Array.isArray(answers.priority)?answers.priority:[answers.priority].filter(Boolean);const context=Object.entries(answers).filter(([key])=>key!=='priority').flatMap(([,value])=>Array.isArray(value)?value:[value]);return option.fit.reduce((score,value)=>score+(context.includes(value)?1:0)+(priority.includes(value)?3:0),0)}
function ResultsSection({type,answers,pathway,onNext,nextLabel,onBack}){const [robotOpen,setRobotOpen]=useState(null);const data=decisionContent[type];const ranked=useMemo(()=>[...data.options].sort((a,b)=>scoreOption(b,answers)-scoreOption(a,answers)),[answers,data]);const custom=otherEntries(pathway,answers);const first=ranked[0];const priorityLabels=pathways[pathway].questions.find(q=>q.id==='priority')?.options.filter(([,v])=>(Array.isArray(answers.priority)?answers.priority:[answers.priority]).includes(v)).map(([label])=>label)||[];const needQuestion=pathways[pathway].questions.find(q=>['funding','need'].includes(q.id));const needLabel=needQuestion?.options.find(([,v])=>v===answers[needQuestion.id])?.[0];const recommendedPros=o=>{const pros=[...o.pros];if(priorityLabels.length)pros.push('Supports your stated priority'+(priorityLabels.length>1?'ies: ':' of ')+priorityLabels.join(', ')+'.');if(needLabel)pros.push('Connects with your stated next need: '+needLabel+'.');while(pros.length<=o.cons.length)pros.push('Offers a path that can be tailored to your selected program, stage, and goals.');return pros};return <section className="decision-screen"><div className="decision-header"><span className="eyebrow">{data.eyebrow}</span><h1>{data.title}</h1><p>{data.intro}</p>{custom.length>0&&<div className="consider"><strong>Your custom selections:</strong> {custom.map(x=>x.text).join(' · ')}</div>}</div><div className="recommendation-intro"><p>Based on your answers, the best option is:</p><h2>{first?.name}</h2></div><div className="option-list">{ranked.map((o,i)=><article className="option-card" key={o.name}><h2>{o.name}{i===0?' — Recommended':''}</h2><div className="columns"><div><h3>Potential advantages</h3><ul>{(i===0?recommendedPros(o):o.pros).map((x,j)=><li key={j}>{x}</li>)}</ul></div><div><h3>Potential drawbacks</h3><ul>{o.cons.map(x=><li key={x}>{x}</li>)}</ul></div></div></article>)}</div><div className="nav-row"><button className="text-button" onClick={onBack}>Back</button><button className="primary" onClick={onNext}>{nextLabel}</button></div></section>}
